#!/usr/bin/env node
/* eslint-disable @typescript-eslint/no-require-imports */

/**
 * Lint open automation-authored PR bodies against required sections.
 *
 * Codifies APR-E05: checks every open automation PR's body for the five
 * required headings and the automation footer, then reports offenders
 * grouped by source workflow.
 *
 * Usage (CI):
 *   node lint-automation-pr-bodies.cjs --repo owner/repo --github-output "$GITHUB_OUTPUT"
 *
 * Usage (standalone):
 *   node lint-automation-pr-bodies.cjs --repo owner/repo
 */

const { execFileSync } = require('child_process');
const fs = require('fs');

const { REQUIRED_HEADINGS } = require('./build-automation-pr-body.cjs');

const AUTOMATION_BRANCH_PREFIXES = ['claude-', 'claude/', 'codex/'];

function getArg(name) {
  const index = process.argv.indexOf(name);
  if (index === -1) return null;
  return process.argv[index + 1] ?? '';
}

function appendOutput(outputPath, key, value) {
  const delimiter = `EOF-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  fs.appendFileSync(
    outputPath,
    `${key}<<${delimiter}\n${String(value ?? '')}\n${delimiter}\n`,
  );
}

function gh(args) {
  return execFileSync('gh', args, {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

/**
 * Detect the source workflow from the PR head branch name.
 * Returns the workflow name (e.g. 'fix-issue', 'audit-auto-prs') or 'unknown'.
 */
function inferWorkflowFromBranch(branchName) {
  const knownPatterns = [
    { pattern: 'claude-workflow-optimize-auto-pr-audit-', workflow: 'audit-auto-prs' },
    { pattern: 'claude-fix-issue-', workflow: 'fix-issue' },
    { pattern: 'claude-suggest-', workflow: 'suggest-improvements' },
    { pattern: 'claude-docs-drift-', workflow: 'docs-drift' },
    { pattern: 'claude-monitor-', workflow: 'monitor-amnezia-control-panel-github-runs' },
    { pattern: 'claude-health-', workflow: 'maintenance' },
    { pattern: 'claude-workflow-health-', workflow: 'workflow-health-optimize' },
    { pattern: 'claude-gsd-planning-', workflow: 'gsd-planning' },
    { pattern: 'claude-gsd-exec-', workflow: 'gsd-planning-execute' },
    { pattern: 'claude-', workflow: 'claude-automation' },
    { pattern: 'claude/', workflow: 'claude-automation' },
    { pattern: 'codex/', workflow: 'codex-automation' },
  ];
  for (const { pattern, workflow } of knownPatterns) {
    if (branchName.startsWith(pattern)) return workflow;
  }
  return 'unknown';
}

/**
 * Test whether `body` contains `heading` as a full line.
 *
 * Anchored to a complete line so prose mentioning the heading text, or a
 * longer heading such as "## What Changed in v2", cannot satisfy the check
 * for "## What Changed". `heading` is treated as a literal (regex-escaped).
 */
function hasHeadingLine(body, heading) {
  const pattern = new RegExp(
    '^' + String(heading).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$',
    'm',
  );
  return pattern.test(String(body || ''));
}

/**
 * Lint a single PR body. Returns { missing: string[], hasFooter: boolean }.
 */
function lintPrBody(body) {
  const missing = REQUIRED_HEADINGS.filter(
    (heading) => !hasHeadingLine(body, heading),
  );
  const hasFooter = /Auto-generated by/i.test(String(body || ''));
  return { missing, hasFooter };
}

/**
 * Collect open automation PRs and lint their bodies.
 * Pure data-path separated from I/O for testability.
 *
 * The PR body is read from `pr.body`, which `gh pr list` already returns.
 * `getBodyFn` is an optional fallback invoked only when the list body is
 * missing or empty, avoiding redundant per-PR `gh pr view` API calls.
 *
 * @param {Array} pullRequests - Array of PR objects from gh pr list
 * @param {Function} [getBodyFn] - Optional (prNumber) => string body fallback
 * @returns {{ inspected: number, offenders: Array, byWorkflow: Object }}
 */
function lintAutomationPrs(pullRequests, getBodyFn) {
  const offenders = [];
  let inspected = 0;

  for (const pr of pullRequests) {
    if (!pr || typeof pr !== 'object') continue;

    const head = String(pr.headRefName ?? '');
    if (!AUTOMATION_BRANCH_PREFIXES.some((p) => head.startsWith(p))) continue;

    inspected++;
    // Prefer the body already fetched by `gh pr list`; fall back to a per-PR
    // fetch only when the list body is missing or empty.
    let body = String(pr.body ?? '');
    if (!body.trim() && getBodyFn) {
      body = getBodyFn(pr.number);
    }
    const { missing, hasFooter } = lintPrBody(body);

    if (missing.length > 0 || !hasFooter) {
      const workflow = inferWorkflowFromBranch(head);
      const issues = [];
      if (missing.length > 0) issues.push(`missing sections: ${missing.join(', ')}`);
      if (!hasFooter) issues.push('missing automation footer');
      offenders.push({
        number: pr.number,
        title: String(pr.title ?? ''),
        branch: head,
        author: String(pr.author?.login ?? ''),
        workflow,
        issues,
      });
    }
  }

  // Group offenders by workflow
  const byWorkflow = {};
  for (const offender of offenders) {
    const wf = offender.workflow;
    if (!byWorkflow[wf]) byWorkflow[wf] = [];
    byWorkflow[wf].push(offender);
  }

  return { inspected, offenders, byWorkflow };
}

function run() {
  const repo = getArg('--repo') || process.env.GITHUB_REPOSITORY;
  const baseRef = getArg('--base-ref') || 'main';
  const outputPath =
    getArg('--github-output') || process.env.GITHUB_OUTPUT || '';
  const jsonOutput = getArg('--json-output') || '';

  if (!repo) {
    process.stderr.write('Error: --repo is required\n');
    process.exit(1);
  }

  // Fetch open automation PRs with body
  let pullRequests;
  try {
    pullRequests =
      JSON.parse(
        gh([
          'pr',
          'list',
          '--repo',
          repo,
          '--state',
          'open',
          '--base',
          baseRef,
          '--limit',
          '100',
          '--json',
          'number,title,headRefName,author,body',
        ]),
      ) || [];
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    process.stderr.write(`::error::gh pr list failed: ${detail}\n`);
    process.exit(1);
  }

  const getBody = (prNumber) => {
    try {
      const pr = JSON.parse(
        gh([
          'pr',
          'view',
          String(prNumber),
          '--repo',
          repo,
          '--json',
          'body',
        ]),
      );
      return pr?.body ?? '';
    } catch {
      return '';
    }
  };

  const result = lintAutomationPrs(pullRequests, getBody);

  // Output structured result
  const report = {
    inspected: result.inspected,
    offender_count: result.offenders.length,
    offenders: result.offenders,
    by_workflow: result.byWorkflow,
  };

  if (outputPath) {
    appendOutput(outputPath, 'offender_count', String(report.offender_count));
    appendOutput(outputPath, 'report', JSON.stringify(report));
  }

  if (jsonOutput) {
    fs.writeFileSync(jsonOutput, JSON.stringify(report, null, 2));
  }

  // Human-readable summary to stdout
  if (result.inspected === 0) {
    process.stdout.write('No open automation PRs to lint.\n');
    return;
  }

  process.stdout.write(
    `Linted ${result.inspected} automation PR(s): ${result.offenders.length} offender(s).\n`,
  );

  if (result.offenders.length > 0) {
    process.stdout.write('\nOffenders:\n');
    for (const offender of result.offenders) {
      process.stdout.write(
        `  #${offender.number} (${offender.workflow}): ${offender.issues.join('; ')}\n`,
      );
    }
    process.stdout.write('\nBy workflow:\n');
    for (const [workflow, prs] of Object.entries(result.byWorkflow)) {
      process.stdout.write(
        `  ${workflow}: ${prs.map((p) => `#${p.number}`).join(', ')}\n`,
      );
    }
  } else {
    process.stdout.write('All automation PR bodies pass quality lint.\n');
  }

  // Exit non-zero when offenders are found so a CI step gating on this
  // script's exit code actually fails — a quality lint that always exits 0
  // enforces nothing.
  if (result.offenders.length > 0) {
    process.exit(1);
  }
}

module.exports = {
  AUTOMATION_BRANCH_PREFIXES,
  inferWorkflowFromBranch,
  lintPrBody,
  lintAutomationPrs,
};

if (require.main === module) {
  run();
}
